234	    /**
235	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
236	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
237	     * Validation already rejects {@code null} values and the pattern-constrained fields
238	     * when blank, but {@code address} and {@code city} have no pattern, so a
239	     * whitespace-only value would otherwise slip through.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields
242	     * @throws RequiredFieldsMissingException if any required field is missing or blank
243	     */
244	    /**
245	     * Common street-type abbreviations expanded during address normalization. Keys are the
246	     * upper-cased abbreviation tokens; values are their canonical expansions.
247	     */
248	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
249	        "ST", "STREET",
250	        "RD", "ROAD",
251	        "AVE", "AVENUE");
252	
253	    /**
254	     * Normalizes the submitted address on create and writes the canonical value back onto the
255	     * request so it is persisted, echoed back, and used for every downstream address comparison
256	     * (household duplicate detection and the household id). The value is trimmed, internal
257	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
258	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
259	     * {@code null} address is left untouched so the required-field check can report it as missing.
260	     *
261	     * @param ownerFieldsDto the submitted owner fields
262	     */
263	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
264	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
265	    }
266	
267	    /**
268	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
269	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
270	     * expanded to its full form. A {@code null} value is returned unchanged.
271	     *
272	     * @param raw the address to canonicalize, possibly {@code null}
273	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
274	     */
275	    private static String normalizeAddress(String raw) {
276	        if (raw == null) {
277	            return null;
278	        }
279	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
280	        if (collapsed.isEmpty()) {
281	            return collapsed;
282	        }
283	        String[] tokens = collapsed.split(" ");
284	        StringBuilder sb = new StringBuilder(collapsed.length());
285	        for (int i = 0; i < tokens.length; i++) {
286	            if (i > 0) {
287	                sb.append(' ');
288	            }
289	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
290	        }
291	        return sb.toString();
292	    }
