294	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
295	        List<String> errors = new ArrayList<>();
296	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
297	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
298	        requireText("address", ownerFieldsDto.getAddress(), errors);
299	        requireText("city", ownerFieldsDto.getCity(), errors);
300	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
301	        if (!errors.isEmpty()) {
302	            throw new RequiredFieldsMissingException(errors);
303	        }
304	    }
