312	    /**
313	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
314	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
315	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
316	     */
317	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
318	        "NSW", new int[] {2000, 2099},
319	        "VIC", new int[] {3000, 3099},
320	        "QLD", new int[] {4000, 4099});
321	
322	    /**
323	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
324	     * {@code null} value is accepted. When present it has already been constrained to four digits
325	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
326	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
327	     * the postcode must fall within that region's inclusive range
328	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
329	     *
330	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
331	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
332	     *                                  city's region
333	     */
334	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
335	        String postcode = ownerFieldsDto.getPostcode();
336	        if (postcode == null) {
337	            return;
338	        }
339	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
340	            .regionFor(ownerFieldsDto.getCity());
341	        int[] range = REGION_POSTCODE_RANGE.get(region);
342	        if (range == null) {
343	            return;
344	        }
345	        int value = Integer.parseInt(postcode);
346	        if (value < range[0] || value > range[1]) {
347	            throw new InvalidPostcodeException(postcode);
348	        }
349	    }
