351	    /**
352	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
353	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
354	     * and echoed back in that form.
355	     *
356	     * @param ownerFieldsDto the submitted owner fields
357	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
358	     *                                        valid E.164 number
359	     */
360	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
361	        String e164 = toE164(ownerFieldsDto.getTelephone());
362	        if (e164 == null) {
363	            throw new RequiredFieldsMissingException(List.of("telephone"));
364	        }
365	        ownerFieldsDto.setTelephone(e164);
366	    }
