368	    /**
369	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
370	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
371	     * and country code are present they are kept; otherwise country code {@code '+61'} is
372	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
373	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
374	     * the national-number length must match the country: {@code '+61'} (Australia) requires
375	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
376	     *
377	     * @param raw the submitted telephone, possibly {@code null}
378	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
379	     */
380	    private static String toE164(String raw) {
381	        if (raw == null) {
382	            return null;
383	        }
384	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
385	        String digits;
386	        if (cleaned.startsWith("+")) {
387	            digits = cleaned.substring(1);
388	        } else {
389	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
390	            digits = "61" + national;
391	        }
392	        if (!digits.matches("[0-9]{8,15}")) {
393	            return null;
394	        }
395	        if (digits.startsWith("61")) {
396	            // Australia: exactly 9 national digits after the '+61' country code.
397	            if (digits.length() - 2 != 9) {
398	                return null;
399	            }
400	        } else if (digits.startsWith("1")) {
401	            // NANP: exactly 10 national digits after the '+1' country code.
402	            if (digits.length() - 1 != 10) {
403	                return null;
404	            }
405	        }
406	        return "+" + digits;
407	    }
