409	    /**
410	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
411	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
412	     * each stored owner's telephone is normalized the same way before comparison so differing
413	     * input formats collapse to the same value.
414	     *
415	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
416	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
417	     *                                     same E.164 telephone
418	     */
419	    /**
420	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
421	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
422	     * the parts may contain whitespace or a second {@code @}.
423	     */
424	    private static final Pattern EMAIL_PATTERN =
425	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
426	
427	    /**
428	     * Normalizes the submitted email when present: the value is trimmed, required to be a
429	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
430	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
431	     *
432	     * @param ownerFieldsDto the submitted owner fields
433	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
434	     */
435	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
436	        String email = ownerFieldsDto.getEmail();
437	        if (email == null) {
438	            return;
439	        }
440	        String trimmed = email.strip();
441	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
442	            throw new InvalidEmailException(email);
443	        }
444	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
445	    }
