447	    /**
448	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
449	     * date. A registration may be back-dated but never post-dated. The check is made against the
450	     * value as supplied, before any defaulting or business-day roll (see
451	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
452	     * to the server date).
453	     *
454	     * @param ownerFieldsDto the submitted owner fields
455	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
456	     *                                         after the server's current date
457	     */
458	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
459	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
460	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
461	            throw new FutureRegistrationDateException(supplied);
462	        }
463	    }
464	
465	    /**
466	     * Establishes the effective registration date on create and rolls it onto a business day.
467	     * When the client does not supply a {@code registrationDate} it defaults to the server's
468	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
469	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
470	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
471	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
472	     * the membership number's year segment and the daily create-limit).
473	     *
474	     * @param ownerFieldsDto the submitted owner fields
475	     */
476	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
477	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
478	        if (effective == null) {
479	            effective = LocalDate.now();
480	        }
481	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
482	    }
483	
484	    /**
485	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
486	     * following Monday; any weekday is returned unchanged.
487	     *
488	     * @param date the date to adjust
489	     * @return the same date when it is a weekday, otherwise the next Monday
490	     */
491	    private static LocalDate toBusinessDay(LocalDate date) {
492	        return switch (date.getDayOfWeek()) {
493	            case SATURDAY -> date.plusDays(2);
494	            case SUNDAY -> date.plusDays(1);
495	            default -> date;
496	        };
497	    }
