499	    /**
500	     * Assigns the owner's {@code customerCode} on create, formatted
501	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
502	     * (preferring the postcode range, falling back to the city — the same derivation that yields
503	     * the owner's {@code locality}, see
504	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
505	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
506	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
507	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
508	     * customer code only when their normalized telephone and last name both match.
509	     *
510	     * @param owner the owner being created (with its {@code postcode}, {@code city},
511	     *              {@code telephone} and {@code lastName} already set)
512	     */
513	    private void assignCustomerCode(Owner owner) {
514	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
515	            .regionFor(owner.getPostcode(), owner.getCity());
516	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
517	            .substring(0, 8).toUpperCase(Locale.ROOT);
518	        owner.setCustomerCode(region + "-" + hash8);
519	    }
