521	    /**
522	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
523	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
524	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
525	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
526	     * canonicalized fields, every owner in the same household — including one joining an existing
527	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
528	     * order.
529	     *
530	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
531	     */
532	    private void assignHouseholdId(Owner owner) {
533	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
534	    }
535	
536	    /**
537	     * Derives the stable {@code householdId} for the given {@code lastName} and {@code address}:
538	     * {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the SHA-256
539	     * digest of the collapsed {@code lastName} and {@code address} (see {@link #collapse}) joined
540	     * by a {@code '\n'}. Because it is derived purely from those two canonicalized fields, every
541	     * owner in the same household receives the same value, independent of create order. Shared by
542	     * {@link #assignHouseholdId} (which persists it) and {@link #identityKeyFor} (which folds it
543	     * into the identity key for duplicate detection).
544	     *
545	     * @param lastName the owner's last name
546	     * @param address  the owner's address
547	     * @return the derived household id
548	     */
549	    private static String householdIdFor(String lastName, String address) {
550	        String key = collapse(lastName) + "\n" + collapse(address);
551	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
552	    }
553	
554	    /**
555	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
556	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
557	     * after this create. Because {@code householdId} is derived from the owner's collapsed
558	     * {@code lastName} and {@code address} (see {@link #assignHouseholdId}), the count reflects every
559	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
560	     * The count is taken before this owner is persisted, so it is one more than the number of
561	     * existing household members.
562	     *
563	     * @param owner the owner being created (with its {@code householdId} already assigned)
564	     */
565	    private void assignHouseholdMemberCount(Owner owner) {
566	        String householdId = owner.getHouseholdId();
567	        long existing = this.clinicService.findAllOwners().stream()
568	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
569	            .count();
570	        owner.setHouseholdMemberCount((int) (existing + 1));
571	    }
572	
573	    /**
574	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
575	     * already share this owner's {@code firstName} and {@code lastName}, compared
576	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
577	     * pre-existing namesakes.
578	     *
579	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
580	     */
581	    private void assignNamesakeCount(Owner owner) {
582	        String firstName = owner.getFirstName();
583	        String lastName = owner.getLastName();
584	        long count = this.clinicService.findAllOwners().stream()
585	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
586	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
587	            .count();
588	        owner.setNamesakeCount((int) count);
589	    }
590	
591	    /**
592	     * Assigns the owner's {@code membershipNumber} on create, formatted
593	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
594	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
595	     * (e.g. {@code 'NSW-A1B2C3D4-M26'}). Derived purely from the owner's own fields, so both
596	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
597	     *
598	     * @param owner the owner being created (with its {@code customerCode} and
599	     *              {@code registrationDate} already set)
600	     */
601	    private void assignMembershipNumber(Owner owner) {
602	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
603	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
604	    }
605	
606	    /**
607	     * The number of owners that must already carry a registration date before a subsequent
608	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
609	     * once the count of owners already registered on that day <em>exceeds</em> this value.
610	     */
611	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
612	
613	    /**
614	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
615	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
616	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
617	     * existing owners before this one is persisted, so it reflects only the owners already
618	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
619	     *
620	     * @param owner the owner being created (with its {@code registrationDate} already set)
621	     */
622	    private void assignBulkSignupWarning(Owner owner) {
623	        LocalDate registrationDate = owner.getRegistrationDate();
624	        long count = this.clinicService.findAllOwners().stream()
625	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
626	            .count();
627	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
628	    }
629	
630	    /**
631	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
632	     *
633	     * @param value the string to hash
634	     * @return the 64-character lower-case hex digest
635	     */
636	    private static String sha256Hex(String value) {
637	        try {
638	            byte[] digest = MessageDigest.getInstance("SHA-256")
639	                .digest(value.getBytes(StandardCharsets.UTF_8));
640	            StringBuilder sb = new StringBuilder(digest.length * 2);
641	            for (byte b : digest) {
642	                sb.append(String.format("%02x", b));
643	            }
644	            return sb.toString();
645	        }
646	        catch (NoSuchAlgorithmException e) {
647	            throw new IllegalStateException("SHA-256 not available", e);
648	        }
649	    }
650	
651	    /**
652	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
653	     * owner. This single key consolidates what used to be three separate duplicate checks
654	     * (telephone, email and household): the key is
655	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
656	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
657	     * matches an existing owner's. Because the telephone is part of the key, two members of the
658	     * same household (same {@code householdId}) with different telephones have different identity
659	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
660	     * and email have already been normalized by {@link #normalizeTelephone} and
661	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
662	     * input formats collapse to the same value.
663	     *
664	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
665	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
666	     *                                    whole identity key
667	     */
668	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
669	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress(),
670	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
671	        boolean duplicate = this.clinicService.findAllOwners().stream()
672	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getAddress(),
673	                owner.getTelephone(), owner.getEmail()))
674	            .anyMatch(identityKey::equals);
675	        if (duplicate) {
676	            throw new DuplicateIdentityException(identityKey);
677	        }
678	    }
679	
680	    /**
681	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
682	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
683	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
684	     * absent), and the {@code householdId} is derived from the collapsed {@code lastName} and
685	     * {@code address} the same way {@link #assignHouseholdId} assigns it (see
686	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
687	     * their whole identities match, regardless of the exact input formats.
688	     *
689	     * @param lastName  the owner's last name
690	     * @param address   the owner's address
691	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
692	     * @param email     the owner's email, possibly {@code null}
693	     * @return the canonical identity key
694	     */
695	    private static String identityKeyFor(String lastName, String address, String telephone, String email) {
696	        String normalizedTelephone = toE164(telephone);
697	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
698	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
699	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, address);
700	    }
701	
702	    /**
703	     * The maximum number of owners permitted in a single city. A create is rejected once the
704	     * owner's city already contains this many owners.
705	     */
706	    private static final long CITY_CAPACITY = 50;
707	
708	    /**
709	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
710	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
711	     * before this owner is persisted.
712	     *
713	     * @param city the submitted city
714	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
715	     */
716	    private void rejectCityAtCapacity(String city) {
717	        long count = this.clinicService.findAllOwners().stream()
718	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
719	            .count();
720	        if (count >= CITY_CAPACITY) {
721	            throw new CityAtCapacityException(city);
722	        }
723	    }
724	
725	    /**
726	     * The maximum number of owners permitted to be created in a single day. A create is
727	     * rejected once this many owners already carry today's {@code registrationDate}.
728	     */
729	    private static final long DAILY_LIMIT = 100;
730	
731	    /**
732	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
733	     * business day as their {@code registrationDate}. The day counted against is this create's
734	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
735	     * so owners are counted per adjusted business day. The count is taken before this owner is
736	     * persisted.
737	     *
738	     * @param businessDay the effective, business-day-adjusted registration date of this create
739	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
740	     */
741	    private void rejectDailyLimit(LocalDate businessDay) {
742	        long count = this.clinicService.findAllOwners().stream()
743	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
744	            .count();
745	        if (count >= DAILY_LIMIT) {
746	            throw new DailyOwnerLimitExceededException(businessDay);
747	        }
748	    }
749	
750	    /**
751	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
752	     * every internal run of whitespace is collapsed to a single space, and the result is
753	     * lower-cased. A {@code null} value collapses to the empty string.
754	     *
755	     * @param value the value to canonicalize, possibly {@code null}
756	     * @return the collapsed, lower-cased value
757	     */
758	    private static String collapse(String value) {
759	        if (value == null) {
760	            return "";
761	        }
762	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
763	    }
764	
765	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
766	    @Override
767	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
768	        Owner owner = this.clinicService.findOwnerById(ownerId);
769	        if (owner != null) {
770	            Pet pet = owner.getPet(petId);
771	            if (pet != null) {
772	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
773	            }
774	        }
775	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
776	    }
777	}
